<script lang="ts">
  // Explains the infinity braid's `connection` parameter with a terminal-box
  // figure. The drawing is generated by scripts/figures/winding-connection.mjs;
  // this component only picks which link layout is visible.
  import "../../assets/iso.css";
  import figure from "../../assets/winding-connection.svg?raw";

  let { value }: { value: number } = $props();

  type Mode = "closed" | "delta" | "star";

  const COPY: Record<Mode, { readout: string; key: string; caption: string }> = {
    closed: {
      readout: "no terminals",
      key: "Splice: joins a coil to itself",
      caption:
        "Each coil's two ends are joined to each other, so nothing reaches the studs. A driver has nowhere to connect, and every coil acts as a shorted turn that drags on the magnets.",
    },
    delta: {
      readout: "V phase = V line",
      key: "Links: join each coil's end to the next coil's start",
      caption:
        "The links join A's end to B's start, B's end to C's start and C's end to A's start. The driver feeds the three joints. On the board, both ends of every phase run out to x = 0, and you make these joints at the connector.",
    },
    star: {
      readout: "V phase = 0.58 × V line",
      key: "Bar: ties the three coil ends into one neutral",
      caption:
        "One bar ties the ends of A, B and C together. The driver feeds the three free starts. On the board, the layer-1 ends join at x = 0 and the layer-0 ends are the terminals.",
    },
  };

  const mode = $derived<Mode>(value === 1 ? "delta" : value === 2 ? "star" : "closed");
  const copy = $derived(COPY[mode]);
</script>

<figure class="iso iso-figure wc-figure" data-theme="dark">
  <div class="iso-plate">
    <div class="iso-plate-corners" aria-hidden="true">
      <span class="iso-plate-corner" data-corner="fig">Fig 1</span>
      <span class="iso-plate-corner" data-corner="title">Winding connection</span>
      <span class="iso-plate-corner" data-corner="hint">{mode}</span>
      <span class="iso-plate-corner" data-corner="readout">{copy.readout}</span>
    </div>
    <div class="wc" data-mode={mode}>
      {@html figure}
    </div>
  </div>
  <figcaption class="iso-legend">
    <span class="iso-keys">
      <span class="iso-key">
        <svg class="iso-swatch" data-mark="lit" viewBox="0 0 16 10" aria-hidden="true">
          <path d="M2 4.5 8 1.5 14 4.5 14 6 8 9 2 6Z" />
          <path class="iso-swatch-crease" d="M2 4.5 8 7.5 14 4.5" />
        </svg>
        {copy.key}
      </span>
    </span>
    <span class="iso-caption">{copy.caption}</span>
  </figcaption>
</figure>

